mapper.select:
SELECT , a.asset_code AS assetCode, a.asset_name AS assetName,
       d.dept_name AS deptName, u.nick_name AS applicantName
FROM ca_scrap s JOIN ca_asset a ON a.asset_id = s.asset_id
LEFT JOIN sys_dept d ON d.dept_id = s.asset_dept_id
LEFT JOIN sys_user u ON u.user_id = s.applicant_user_id
WHERE 1=1 

    AND (s.scrap_no LIKE CONCAT('%',#{keyword},'%') OR a.asset_code LIKE CONCAT('%',#{keyword},'%')
         OR a.asset_name LIKE CONCAT('%',#{keyword},'%'))

AND s.status = #{status}
AND s.status IN ('2','3')
AND s.dispose_type=#{disposeType}
AND s.asset_dept_id = #{deptId}
AND u.nick_name LIKE CONCAT('%',#{applicant},'%')
AND s.apply_time >= #{beginTime}
AND s.apply_time <= #{endTime}
ORDER BY s.scrap_id DESC

mapper.update:
UPDATE ca_scrap SET status=#{status},update_by=#{operator},update_time=NOW(3),
    completed_time=CASE WHEN #{status}='3' THEN NOW(3) ELSE completed_time END
WHERE scrap_id=#{id} AND status=#{expected}
